// relayOption allows management of the mutation configuration using functional options.
type relayOption func(*RelayMutation)

// newRelayMutation creates new mutation for the Relay entity.
func newRelayMutation(c config, op Op, opts ...relayOption) *RelayMutation {
	m := &RelayMutation{
		Mutation: *relay.NewMutation(op),
		config:   c,
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// SetId sets the value of the id field. Note that this
